async function initDB() {
  const pool = mysql.createPool({
    host: process.env.DB_HOST || 'localhost',
    user: process.env.DB_USER || 'root',
    password: process.env.DB_PASS || '',
    database: 'blog_app',
    waitForConnections: true,
    connectionLimit: 10
  });

  await pool.execute(`
    CREATE TABLE IF NOT EXISTS posts (
      id INT PRIMARY KEY AUTO_INCREMENT,
      title VARCHAR(200) NOT NULL,
      content TEXT,
      user_id INT DEFAULT 1,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
  `);

  console.log('数据库初始化完成');
  return pool;
}

module.exports = initDB;

const express = require('express');
const mysql = require('mysql2/promise');
const app = express();
app.use(express.json());

const pool = mysql.createPool({
  host: 'localhost', user: 'root', password: '', database: 'blog_app'
});

// 获取文章列表 (分页)
app.get('/api/posts', async (req, res) => {
  try {
    const page = Math.max(1, +req.query.page || 1);
    const limit = Math.min(50, Math.max(1, +req.query.limit || 10));
    const offset = (page - 1) * limit;
    const [rows] = await pool.execute(
      'SELECT id, title, LEFT(content,100) as excerpt, user_id, created_at FROM posts ORDER BY created_at DESC LIMIT ? OFFSET ?',
      [limit, offset]
    );
    const [countRes] = await pool.execute('SELECT COUNT(*) as total FROM posts');
    res.json({ data: rows, page, total: countRes[0].total });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// 创建文章
app.post('/api/posts', async (req, res) => {
  const { title, content } = req.body;
  if (!title) return res.status(400).json({ error: '标题必填' });
  try {
    const [result] = await pool.execute(
      'INSERT INTO posts (title, content) VALUES (?, ?)',
      [title, content || '']
    );
    res.status(201).json({ id: result.insertId, title, content });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.listen(3000, () => console.log('Blog API on :3000'));

